arguments.command:
printf '\n--- numerical stream insertion ---\n'
sed -n '58,98p' /build/gcc-13.2.0/libstdc++-v3/include/bits/ostream.tcc
printf '\n--- exception pool cleanup hook ---\n'
sed -n '363,397p' /build/gcc-13.2.0/libstdc++-v3/libsupc++/eh_alloc.cc
printf '\n--- first confirmed allocator errors ---\n'
sed -n '1,90p' /tmp/app-crash-check.WDDZFS/release.native-alloc.valgrind
printf '\n--- applying user.cpp-only fix ---\n'
cp /app/user.cpp /tmp/app-crash-check.WDDZFS/user.original.cpp
python3 - <<'PY'
from pathlib import Path
path = Path('/app/user.cpp')
source = path.read_text()
source = source.replace('''#include "user.h"

void user_init() {
}

void user_cleanup() {
}
''', '''#include "user.h"
#include <sstream>

// libstdc++ provides this hook to release its emergency exception pool.
// Valgrind cannot invoke it automatically when the library is linked statically.
namespace __gnu_cxx {
void __freeres() noexcept;
}

void user_init() {
    // The custom library lazily registers locale facets for destruction after
    // main(). Initialize them while global new still uses the system heap,
    // not the application's shorter-lived custom heap. Exercise the numeric
    // formatting paths too, without changing std::cout or producing output.
    std::ostringstream warmup;
    warmup << 0 << 0.0;
}

void user_cleanup() {
    // Application shutdown has already restored the system allocator.
    __gnu_cxx::__freeres();
}
''')
path.write_text(source)
PY
printf '\n--- source diff ---\n'
diff -u /tmp/app-crash-check.WDDZFS/user.original.cpp /app/user.cpp || test "$?" -eq 1
printf '\n--- re-running reproduction ---\n'
/tmp/app-crash-check.WDDZFS/reproduce.sh
